python3 << 'EOF'
from openpyxl import load_workbook

wb = load_workbook('sales_data.xlsx')
ws = wb.active

# Print headers and values for each row
print("=== Cell values (as stored, incl. formulas) ===")
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    for cell in row:
        if cell.value is not None:
            print(f"{cell.coordinate}: {repr(cell.value)}")
    print("---")

print("\n=== Column widths ===")
for col_letter, dim in ws.column_dimensions.items():
    print(col_letter, dim.width)

print("\n=== Merged cells ===", ws.merged_cells.ranges)

print("\n=== Sample number formats ===")
for cell in ws['1']:
    if cell.value is not None:
        print(cell.coordinate, 'format:', repr(cell.number_format), 'font bold:', cell.font.bold)
for row in ws.iter_rows(min_row=2, max_row=3):
    for cell in row:
        if cell.value is not None:
            print(cell.coordinate, 'format:', repr(cell.number_format))
EOF
